// ❌ OLD: 15 lines of boilerplate to handle fetching, loading states,
// error states, and unmount cancellation.
import { useState, useEffect } from 'react';

export default function UserProfile({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchUser(userId).then((data) => {
      setUser(data);
      setLoading(false);
    });
  }, [userId]);

  if (loading) return <div>Loading...</div>;
  return <h1>{user.name}</h1>;
}

import { use, Suspense } from 'react';

// ✅ NEW: Promise passed directly from server or cache.
// use() unwraps it and suspends automatically.
function UserDetail({ userPromise, showDetails }) {
  if (!showDetails) return <div>Details hidden</div>;

  // ✅ Legal to call inside conditional block!
  const user = use(userPromise);
  return <h1>{user.name}</h1>;
}

export default function UserProfile({ userPromise }) {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <UserDetail userPromise={userPromise} showDetails={true} />
    </Suspense>
  );
}
